const p = $json.body || {};
if (!p.company) throw new Error('company is required');

const clean = v => String(v || '').trim();
const sources = [];
if (p.source) sources.push(clean(p.source));
if (p.website) sources.push('Existing prospect data');

return [{
  json: {
    ...p,
    company: clean(p.company),
    city: clean(p.city),
    country: clean(p.country),
    niche: clean(p.niche),
    phone: clean(p.phone),
    email: clean(p.email),
    website: clean(p.website),
    wikidata: clean(p.wikidata),
    osmId: clean(p.id || p.osm_id),
    sources: [...new Set(sources)],
    website_candidate: clean(p.website),
    discovery_attempted: false,
    discovery_method: '',
    discovery_notes: []
  }
}];

const src = $('Prepare Enrichment').first().json;
const data = $input.first().json || {};
const entity = data.entities?.[src.wikidata] || {};
const claims = entity.claims || {};

const claimValue = (pid) => {
  const rows = claims[pid] || [];
  for (const r of rows) {
    const v = r?.mainsnak?.datavalue?.value;
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
};

const website = claimValue('P856');
const phone = claimValue('P1329');
const email = claimValue('P968');

return [{
  json: {
    ...src,
    discovery_attempted: true,
    discovery_method: 'Wikidata',
    wikidataWebsite: website,
    wikidataPhone: phone,
    wikidataEmail: email,
    website_candidate: src.website || website || '',
    discovery_notes: [
      ...(src.discovery_notes || []),
      website ? 'Official website candidate found in Wikidata' : 'No official website in Wikidata',
      phone ? 'Phone found in Wikidata' : 'No phone in Wikidata',
      email ? 'Email found in Wikidata' : 'No email in Wikidata'
    ]
  }
}];

const src = $('Prepare Enrichment').first().json;
return [{
  json: {
    ...src,
    discovery_attempted: true,
    discovery_method: 'No linked discovery source',
    discovery_notes: [
      ...(src.discovery_notes || []),
      'No Wikidata id supplied by current prospect source',
      'No generic search-engine scraping is performed'
    ]
  }
}];

const src = $('Has Website Candidate?').first().json;
const raw = $input.first().json;
let html = '';
if (typeof raw === 'string') html = raw;
else if (raw && typeof raw.data === 'string') html = raw.data;
else html = JSON.stringify(raw || {});

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const companyTokens = norm(src.company).split(' ').filter(x => x.length >= 4);
const cityTokens = norm(src.city).split(' ').filter(x => x.length >= 4);
const pageNorm = norm(html.slice(0, 250000));

const companyHits = companyTokens.filter(t => pageNorm.includes(t)).length;
const cityHits = cityTokens.filter(t => pageNorm.includes(t)).length;

const emails = [...new Set([
  ...[...html.matchAll(/mailto:([^"'?<>\s]+)/gi)].map(m=>m[1]),
  ...(html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)||[])
])].filter(e => !/example\.|sentry\.|wixpress\.|cloudflare/i.test(e));

const phones = [...new Set([
  ...[...html.matchAll(/tel:([^"'<>\s]+)/gi)].map(m=>m[1]),
  ...(html.match(/(?:\+?1[\s().-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/g)||[])
])];

const links = [...html.matchAll(/href=["']([^"']+)["']/gi)].map(m=>m[1]);
const contact = links.find(h => /contact|quote|estimate|get-in-touch/i.test(h)) || '';
let contactUrl = '';
if (contact) { try { contactUrl = new URL(contact, src.website_candidate).href; } catch {} }

return [{
  json: {
    ...src,
    website_live: html.length > 200,
    company_match_hits: companyHits,
    city_match_hits: cityHits,
    homepageEmail: emails[0] || '',
    homepagePhone: phones[0] || '',
    contactUrl,
    homepageChecked: true
  }
}];

const src = $('Validate And Extract Website').first().json;
const raw = $input.first().json;
let html = '';
if (typeof raw === 'string') html = raw;
else if (raw && typeof raw.data === 'string') html = raw.data;
else html = JSON.stringify(raw || {});

const emails = [...new Set([
  ...[...html.matchAll(/mailto:([^"'?<>\s]+)/gi)].map(m=>m[1]),
  ...(html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)||[])
])].filter(e => !/example\.|sentry\.|wixpress\.|cloudflare/i.test(e));

const phones = [...new Set([
  ...[...html.matchAll(/tel:([^"'<>\s]+)/gi)].map(m=>m[1]),
  ...(html.match(/(?:\+?1[\s().-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}/g)||[])
])];

return [{
  json: {
    ...src,
    contactPageChecked: true,
    contactPageEmail: emails[0] || '',
    contactPagePhone: phones[0] || ''
  }
}];

const p = $json;
const website = p.website_candidate || p.website || '';
const email = p.contactPageEmail || p.homepageEmail || p.wikidataEmail || p.email || '';
const phone = p.contactPagePhone || p.homepagePhone || p.wikidataPhone || p.phone || '';

let confidence = 0;
const evidence = [];
const provenance = {};

if (p.osmId || (p.sources || []).includes('OpenStreetMap')) {
  confidence += 15;
  evidence.push('OSM record present');
}
if (p.wikidata) {
  confidence += 10;
  evidence.push('Linked Wikidata entity present');
}
if (website) {
  confidence += 15;
  provenance.website = p.wikidataWebsite ? 'Wikidata P856 / existing prospect data' : 'Existing prospect data';
  evidence.push('Website candidate present');
}
if (p.website_live) {
  confidence += 15;
  evidence.push('Website reachable');
}
if ((p.company_match_hits || 0) >= 1) {
  confidence += 15;
  evidence.push('Company name matches website content');
}
if ((p.city_match_hits || 0) >= 1) {
  confidence += 10;
  evidence.push('City matches website content');
}
if (email) {
  confidence += 10;
  provenance.email = p.contactPageEmail ? 'Official website contact page'
    : p.homepageEmail ? 'Official website homepage'
    : p.wikidataEmail ? 'Wikidata'
    : 'Existing prospect data';
  evidence.push('Public business email found');
}
if (phone) {
  confidence += 10;
  provenance.phone = p.contactPagePhone ? 'Official website contact page'
    : p.homepagePhone ? 'Official website homepage'
    : p.wikidataPhone ? 'Wikidata'
    : 'Existing prospect data';
  evidence.push('Public business phone found');
}

confidence = Math.min(100, confidence);

let verification_status = 'Needs verification';
if (website && p.website_live && (email || phone) && (p.company_match_hits || 0) >= 1 && confidence >= 70) {
  verification_status = 'Verified';
}

return [{
  json: {
    company: p.company,
    city: p.city || '',
    country: p.country || '',
    niche: p.niche || '',
    website,
    email,
    phone,
    verification_status,
    confidence,
    contactable: Boolean(email || phone),
    discovery_attempted: Boolean(p.discovery_attempted),
    discovery_method: p.discovery_method || '',
    evidence,
    provenance,
    discovery_notes: p.discovery_notes || [],
    safe_to_outreach: verification_status === 'Verified',
    notes: verification_status === 'Verified'
      ? 'Prospect passed linked-source and official-site verification.'
      : 'Prospect still needs verification. Do not claim that no website exists.',
    enriched_at: new Date().toISOString()
  }
}];
